○整数型: func1(整数型: n)
    if (n ≦ 2)
        return 1
    endif
    return 2 × func1(n - 2) + func1(n - 1)

○整数型: func2(整数型: n)
    整数型の配列: data ← {1, 1, 1}
    整数型: i
    /* nが3より小さい場合は繰返し処理を実行しない */
    for (iを3からnまで1ずつ増やす)
        data[1] ← data[2]
        data[2] ← data[3]
        data[3] ← 【a】
    endfor
    return data[3]
